window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-28a2df09dd509aea"]={"versions": [{"id": "FIG-28a2df09dd509aea", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-/Aktivitäts-Notation nach AUTOSAR-Methodology-Standard). Der Kontext ist der Build- und Integrationsprozess von Basissoftware (BSW), speziell die Kompilierung eines konfigurierten BSW-Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task:</strong>\n<ul class=\"fig-list\"><li><code>Compile Configured BSW</code>: Auszuführende Compiler-Aktivität (dargestellt als pfeilförmiges Aktivitätssymbol).\n</li></ul>\n</li><li><strong>Werkzeug:</strong>\n<ul class=\"fig-list\"><li><code>Compiler</code>: Verwendetes Werkzeug (Stereotyp <code>«used tool»</code>, Hammersymbol).\n</li></ul>\n</li><li><strong>Eingangs-Artefakte (<code>«input»</code>, jeweils Multiplizität 1):</strong>\n<ul class=\"fig-list\"><li><code>BSW Module Configuration Header File</code>: Modulspezifische Konfigurations-Headerdatei (.h).\n</li><li><code>Basic Software Module Core Header</code>: Kern-Headerdatei des BSW-Moduls.\n</li><li><code>Basic Software Module Source Code</code>: Quellcodedatei des BSW-Moduls (unten abgeschnitten beschriftet).\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (<code>«output»</code>, Multiplizität <code>1..*</code>):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code>: Kompiliertes Objektcode-Artefakt (mindestens ein Objektfile).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Compile Configured BSW</code> nimmt drei Quell-Artefakte mit jeweiliger Multiplizität 1 entgegen: den Konfigurations-Header (<code>BSW Module Configuration Header File</code>), den Modul-Kern-Header (<code>Basic Software Module Core Header</code>) sowie den zugehörigen Quellcode (<code>Basic Software Module Source Code</code>). Unter Einsatz des Werkzeugs <code>Compiler</code> (<code>«used tool»</code>) werden diese Artefakte kompiliert und erzeugen als Ergebnis ein oder mehrere Objektcode-Artefakte (<code>Basic Software Module Object Code</code>, Kanten-Multiplizität <code>1..*</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Build-Umgebungen müssen sicherstellen, dass vor dem Kompiliervorgang sowohl die statischen Quell- und Header-Dateien als auch die generierten Konfigurations-Header bereitstehen. Die Ausgabe-Kardinalität von mindestens einem Objektcode-Artefakt (<code>1..*</code>) gestattet es dem Kompilierschritt, ein oder mehrere kompilierte Objektdateien für das konfigurierte BSW-Modul hervorzubringen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b659dca7941962e", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">AUTOSAR-Methodik-Aktivitätsdiagramm (SPEM-/Aktivitäts-Notation nach AUTOSAR-Methodology-Standard). Der Kontext ist der Build- und Integrationsprozess von Basissoftware (BSW), speziell die Kompilierung eines konfigurierten BSW-Moduls.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Aktivität / Task:</strong>\n<ul class=\"fig-list\"><li><code>Compile Configured BSW</code>: Auszuführende Compiler-Aktivität (dargestellt als pfeilförmiges Aktivitätssymbol).\n</li></ul>\n</li><li><strong>Werkzeug:</strong>\n<ul class=\"fig-list\"><li><code>Compiler</code>: Verwendetes Werkzeug (Stereotyp <code>«used tool»</code>, Hammersymbol).\n</li></ul>\n</li><li><strong>Eingangs-Artefakte (<code>«input»</code>, jeweils Multiplizität 1):</strong>\n<ul class=\"fig-list\"><li><code>BSW Module Configuration Header File</code>: Modulspezifische Konfigurations-Headerdatei (.h).\n</li><li><code>Basic Software Module Core Header</code>: Kern-Headerdatei des BSW-Moduls.\n</li><li><code>Basic Software Module Source Code</code>: Quellcodedatei des BSW-Moduls.\n</li></ul>\n</li><li><strong>Ausgangs-Artefakt (<code>«output»</code>, Multiplizität 1):</strong>\n<ul class=\"fig-list\"><li><code>Basic Software Module Object Code</code>: Kompiliertes Objektcode-Artefakt (genau eine Objektdatei).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Aktivität <code>Compile Configured BSW</code> nimmt drei Quell-Artefakte mit jeweiliger Multiplizität 1 entgegen: den Konfigurations-Header (<code>BSW Module Configuration Header File</code>), den Modul-Kern-Header (<code>Basic Software Module Core Header</code>) sowie den zugehörigen Quellcode (<code>Basic Software Module Source Code</code>). Unter Einsatz des Werkzeugs <code>Compiler</code> (<code>«used tool»</code>) werden diese Artefakte kompiliert und erzeugen als Ergebnis genau ein Objektcode-Artefakt (<code>Basic Software Module Object Code</code>, Kanten-Multiplizität 1).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Build-Umgebungen müssen sicherstellen, dass vor dem Kompiliervorgang sowohl die statischen Quell- und Header-Dateien als auch die generierten Konfigurations-Header bereitstehen. Die Ausgabe-Kardinalität von genau 1 legt fest, dass der Kompilierschritt pro Aufruf genau ein Objektcode-Artefakt für das konfigurierte BSW-Modul erzeugt.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-28a2df09dd509aea", "to": "FIG-9b659dca7941962e", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Kardinalität an der Ausgabekante «output» zu <code>Basic Software Module Object Code</code>: von <code>1..*</code> (im Bild abgeschnitten als <code>1..</code>) auf exakt <code>1</code> geändert.\n</li></ul>"}]};
